                $last=self::col(count($rows[0]));$xml='<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews><cols><col min="1" max="'.count($rows[0]).'" width="26" customWidth="1"/></cols><sheetData>';
                foreach($rows as $ri=>$values){$xml.='<row r="'.($ri+1).'"'.($ri?' ht="72" customHeight="1"':'').'>';
                    foreach($values as $ci=>$value){if(is_array($value))$value=wp_json_encode($value);$value=(string)$value;if(mb_strlen($value)>32767)$value='Long content: open the secure WordPress Review Studio using the Stable ID in this row; no text has been truncated in the database.';
                        $style=$ri?('Approval Decisions'===$name&&$ci>=3?2:1):0;if($ri&&$name==='Question Review'){$subjects=array('FR','AFM','AUDIT','DT','IDT','IBS');$index=array_search($values[2]??'', $subjects,true);if(false!==$index)$style=3+$index;}$xml.='<c r="'.self::col($ci+1).($ri+1).'" t="inlineStr" s="'.$style.'"><is><t xml:space="preserve">'.self::xml($value).'</t></is></c>';
                    }$xml.='</row>';
                }$xml.='</sheetData><sheetProtection sheet="1" objects="1" scenarios="1" autoFilter="0" selectUnlockedCells="0"/><autoFilter ref="A1:'.$last.count($rows).'"/>';
                if('Approval Decisions'===$name&&count($rows)>1){$simple=($rows[0][3]??'')==='Owner Decision';$xml.='<dataValidations count="1"><dataValidation type="list" allowBlank="1" showErrorMessage="1" errorTitle="Choose a decision" error="Use Approve, Hold, Reject or leave blank" sqref="D2:'.($simple?'D':'K').count($rows).'"><formula1>"'.($simple?'Needs Review,Publish,Reject':'Approve,Hold,Reject').'"</formula1></dataValidation></dataValidations>';}
                $zip->addFromString('xl/worksheets/sheet'.$idx.'.xml',$xml.'</worksheet>');
