    }
    public static function export($ids){
        if(is_wp_error($e=CAFCC_Studio::admin()))return $e;if(!is_array($ids)||!array_is_list($ids)||!count($ids)||count($ids)>100)return CAFCC_Repository::error('Select 1–100 rows per workbook.');$rows=array();foreach(array_unique($ids) as $id){$id=CAFCC_Repository::id($id);if(is_wp_error($id))return $id;$r=CAFCC_Studio::detail($id);if(is_wp_error($r))return $r;if(!$r)return CAFCC_Repository::error('Review row not found.');$rows[]=$r;}
        $batch=wp_generate_uuid4();$manifest=array('owner'=>get_current_user_id(),'issued'=>time(),'expires'=>time()+7*DAY_IN_SECONDS,'records'=>array());$sheets=array_fill_keys(self::SHEETS,array());
        $sheets['Question Review'][]=array('Stable ID','Revision','Subject','Attempt','RTP/MTP/Exam','Series','Source PDF','Question Number','Subpart','Full permitted Question Text','Full permitted Answer Text','Chapter / Unit / Topic / Subtopic IDs','Other Tags','Official URL','Question Page','Answer Page','AI Classification / Evidence','Correction instructions','Reviewer Notes','Chapter','ICAI Unit','Topic','Subtopic');
        $sheets['Answer Review'][]=array('Stable ID','Question','Subpart','Answer Source Hash','Answer Reference','Answer Page','Official Answer URL','Permitted Review Answer');
        $sheets['Syllabus Mapping'][]=array('Stable ID','Edition ID','Node IDs','Historical Law / Scheme','Classification Reasoning');$sheets['Source Register'][]=array('Stable ID','Source Key','SHA-256','Source Revision','Official URL','Scheme');$sheets['Exceptions'][]=array('Stable ID','Warnings','Confidence','Extraction Status');
        $sheets['Approval Decisions'][]=array_merge(array('Stable ID','Revision','Source Hash'),CAFCC_Studio::STAGES,array('publication','Corrected Node IDs (comma separated)','Reviewer Notes'));
        $sheets['Batch Manifest'][]=array('Key','Value');$sheets['Batch Manifest'][]=array('batch_key',$batch);$sheets['Batch Manifest'][]=array('format','CAFCC-XLSX-1');$sheets['Batch Manifest'][]=array('instructions','Only Approval Decisions is editable. Mark each stage separately. Publication is a separate explicit Approve. Corrections reset affected approvals. Upload → Validate → inspect conflicts → Apply. No macros; changing this file alone does not change WordPress. IDs/hashes are checked against a private server manifest. Expires in seven days. Never share this private book.');
        $sheets['Progress Summary'][]=array('Measure','Value');$sheets['Progress Summary'][]=array('Exported rows',count($rows));$sheets['Progress Summary'][]=array('Published eligible',count(array_filter($rows,function($r){return $r['publication_status']==='published';})));$sheets['Progress Summary'][]=array('Needs further review',count(array_filter($rows,function($r){return $r['status']!=='approved';})));
        foreach($rows as $r){$d=$r['data'];$a=$d['answer'];$manifest['records'][$r['stable_id']]=array('id'=>(int)$r['id'],'revision'=>(int)$r['revision'],'source_hash'=>$r['source_hash']);
            $sheets['Question Review'][]=array($r['stable_id'],$r['revision'],$d['subject_code'],$d['exam_attempt'],$d['source_type'],$d['mtp_series'],$d['source_key'],$d['reference'],$d['subreference'],($d['rich_content']['question']['body_html']??($d['review_question_text']?:($r['practice_preview']['question']['body_html']??''))),($d['rich_content']['answer']['body_html']??($d['review_answer_text']?:($r['practice_preview']['answer']['body_html']??''))),implode(',',$d['classification']),'',$d['official_url'],$d['question_page'],$a['page']??'',$d['reasoning'],'Edit decisions/corrected IDs in Approval Decisions; use Studio for other corrections.',$d['review_notes'],$d['classification_context']['chapter']['title']??'',$d['classification_context']['unit']['title']??'',$d['classification_context']['topic']['title']??'',$d['classification_context']['subtopic']['title']??'');
            $sheets['Answer Review'][]=array($r['stable_id'],$d['reference'],$d['subreference'],$a['source_hash']??'',$a['reference']??'',$a['page']??'',$a['official_url']??'',($d['rich_content']['answer']['body_html']??($d['review_answer_text']?:($r['practice_preview']['answer']['body_html']??''))));$sheets['Syllabus Mapping'][]=array($r['stable_id'],$d['edition_id'],implode(',',$d['classification']),$d['scheme'].' · '.$d['law_context'],$d['reasoning']);$sheets['Source Register'][]=array($r['stable_id'],$d['source_key'],$r['source_hash'],$d['source_revision'],$d['official_url'],$d['scheme']);$sheets['Exceptions'][]=array($r['stable_id'],wp_json_encode($d['exceptions']),$d['confidence'],$d['extraction_status']);$sheets['Approval Decisions'][]=array_merge(array($r['stable_id'],$r['revision'],$r['source_hash']),array_fill(0,8,''),array('',''));
        }
        $encoded=self::encode($sheets);if(is_wp_error($encoded))return $encoded;
        global $wpdb;if(false===$wpdb->insert(CAFCC_Bank_DB::table('batches'),array('batch_key'=>$batch,'owner_id'=>get_current_user_id(),'batch_type'=>'excel','status'=>'exported','manifest'=>wp_json_encode($manifest),'created_at'=>current_time('mysql',true))))return CAFCC_Repository::error('Cannot retain export manifest.',500);
        return array('filename'=>'cafcc-review-'.$batch.'.xlsx','base64'=>$encoded,'rows'=>count($rows),'expires_at'=>gmdate('c',$manifest['expires']));
    }
    private static function parse_xml($xml,$limit=40000){if(!is_string($xml)||preg_match('/<!DOCTYPE|<!ENTITY/i',$xml)||substr_count($xml,'<')>$limit)throw new RuntimeException('External entities and DTDs are forbidden.');$old=libxml_use_internal_errors(true);try{$doc=simplexml_load_string($xml,'SimpleXMLElement',LIBXML_NONET);if(!$doc)throw new RuntimeException('Invalid workbook XML.');return $doc;}finally{libxml_clear_errors();libxml_use_internal_errors($old);}}
    public static function decode($encoded,$allowed_sheets=null){
        $allowed_sheets=$allowed_sheets??self::SHEETS;$xml_limit=$allowed_sheets===self::SHEETS?40000:250000;$row_limit=$allowed_sheets===self::SHEETS?1000:5000;
        if(!function_exists('wp_tempnam'))require_once ABSPATH.'wp-admin/includes/file.php';
        if(!is_string($encoded)||strlen($encoded)>4000000)throw new RuntimeException('Use a workbook under 3 MB.');$bytes=base64_decode($encoded,true);if(false===$bytes||substr($bytes,0,2)!=='PK')throw new RuntimeException('Upload a valid XLSX workbook.');
        if(!class_exists('ZipArchive'))throw new RuntimeException('PHP ZIP extension unavailable.');$tmp=wp_tempnam('cafcc-upload');file_put_contents($tmp,$bytes);$zip=new ZipArchive();
        try{if(true!==$zip->open($tmp))throw new RuntimeException('Invalid ZIP.');$size=0;if($zip->numFiles>150)throw new RuntimeException('Too many workbook parts.');
            for($i=0;$i<$zip->numFiles;$i++){$st=$zip->statIndex($i);$name=$st['name'];$size+=$st['size'];if($st['size']>6500000||$size>16000000||str_contains($name,'..')||str_starts_with($name,'/')||preg_match('/vba|externalLink|\.bin$/i',$name))throw new RuntimeException('Unsafe/oversized workbook part.');if(str_ends_with($name,'.rels')&&preg_match('/TargetMode\s*=\s*[\'"]External/i',$zip->getFromIndex($i)))throw new RuntimeException('External workbook relationships are forbidden.');}
            $shared=array();$ss=$zip->getFromName('xl/sharedStrings.xml');if(false!==$ss){$d=self::parse_xml($ss);foreach($d->children('http://schemas.openxmlformats.org/spreadsheetml/2006/main')->si as $si){$texts=$si->xpath('.//*[local-name()="t"]');$s='';foreach($texts as $t)$s.=(string)$t;$shared[]=$s;}}
            $wb=self::parse_xml($zip->getFromName('xl/workbook.xml'));$rels=self::parse_xml($zip->getFromName('xl/_rels/workbook.xml.rels'));$targets=array();foreach($rels->children('http://schemas.openxmlformats.org/package/2006/relationships')->Relationship as $rel)$targets[(string)$rel->attributes()['Id']]=(string)$rel->attributes()['Target'];$out=array();
            foreach($wb->children('http://schemas.openxmlformats.org/spreadsheetml/2006/main')->sheets->sheet as $sheet){$name=(string)$sheet->attributes()['name'];if(!in_array($name,$allowed_sheets,true))throw new RuntimeException('Unexpected worksheet.');$attrs=$sheet->attributes('http://schemas.openxmlformats.org/officeDocument/2006/relationships');$target=$targets[(string)$attrs['id']]??'';$target=ltrim($target,'/');if(!str_starts_with($target,'xl/'))$target='xl/'.$target;if(!preg_match('~^xl/worksheets/sheet[0-9]+\.xml$~D',$target))throw new RuntimeException('Unsafe worksheet location.');
                $xml=self::parse_xml($zip->getFromName($target),$xml_limit);$rows=array();foreach($xml->children('http://schemas.openxmlformats.org/spreadsheetml/2006/main')->sheetData->row as $row){if(count($rows)>$row_limit)throw new RuntimeException('Too many workbook rows.');$cells=array();foreach($row->c as $cell){if(isset($cell->f))throw new RuntimeException('Formula cells are not accepted in review uploads.');$ref=(string)$cell->attributes()['r'];if(!preg_match('/^([A-Z]{1,2})[1-9][0-9]{0,5}$/D',$ref,$m))throw new RuntimeException('Invalid cell reference.');$ci=0;foreach(str_split($m[1]) as $letter)$ci=$ci*26+ord($letter)-64;$ci--;if($ci>60)throw new RuntimeException('Unexpected workbook column.');$value=(string)$cell->v;$type=(string)$cell->attributes()['t'];if('s'===$type){if(!ctype_digit($value)||!isset($shared[(int)$value]))throw new RuntimeException('Invalid shared string.');$value=$shared[(int)$value];}elseif('inlineStr'===$type){$value='';foreach($cell->xpath('.//*[local-name()="t"]') as $t)$value.=(string)$t;}$cells[$ci]=$value;}if($cells){$max=max(array_keys($cells));$values=array_fill(0,$max+1,'');foreach($cells as $i=>$v)$values[$i]=$v;$rows[]=$values;}}
                $out[$name]=$rows;
            }if(count($out)!==8)throw new RuntimeException('Keep all eight workbook sheets.');return $out;
        }finally{$zip->close();unlink($tmp);}
    }
    public static function preview($encoded){
        if(is_wp_error($e=CAFCC_Studio::admin()))return $e;try{$book=self::decode($encoded);}catch(Throwable $e){return CAFCC_Repository::error($e->getMessage());}
        $pairs=$book['Batch Manifest'];$key='';foreach($pairs as $pair)if(($pair[0]??'')==='batch_key')$key=$pair[1]??'';if(!preg_match('/^[a-f0-9-]{36}$/D',$key))return CAFCC_Repository::error('Unknown workbook manifest.');global $wpdb;$t=CAFCC_Bank_DB::table('batches');$batch=$wpdb->get_row($wpdb->prepare("SELECT * FROM $t WHERE batch_key=%s AND batch_type='excel'",$key),ARRAY_A);if(!$batch||(int)$batch['owner_id']!==get_current_user_id()||$batch['status']!=='exported')return CAFCC_Repository::error('Workbook was not issued to this administrator or was already applied.',409);$manifest=json_decode($batch['manifest'],true);if($manifest['expires']<time())return CAFCC_Repository::error('Workbook expired. Export current revisions.',409);
        $headers=array_merge(array('Stable ID','Revision','Source Hash'),CAFCC_Studio::STAGES,array('publication','Corrected Node IDs (comma separated)','Reviewer Notes'));if(($book['Approval Decisions'][0]??array())!==$headers)return CAFCC_Repository::error('Approval Decisions columns changed.');
        $decisions=array();$errors=array();$seen=array();$i=0;foreach(array_slice($book['Approval Decisions'],1) as $line){$i++;$line=array_pad($line,13,'');$sid=$line[0];$signed=$manifest['records'][$sid]??null;if(!$signed||isset($seen[$sid])||(string)$signed['revision']!==$line[1]||$signed['source_hash']!==$line[2]){$errors[]=array('row'=>$i+1,'message'=>'Unknown, duplicate or altered immutable ID/revision/source hash.');continue;}$seen[$sid]=true;$row=CAFCC_Studio::get($signed['id']);if(!$row||(int)$row['revision']!==$signed['revision']){$errors[]=array('row'=>$i+1,'message'=>'Stale workbook: WordPress has a newer correction.');continue;}
            $actions=array();foreach(array_merge(CAFCC_Studio::STAGES,array('publication')) as $ci=>$stage){$value=$line[3+$ci]??'';if(!in_array($value,array('','Approve','Hold','Reject'),true)){$errors[]=array('row'=>$i+1,'message'=>'Invalid decision: '.$stage);continue;}if($value)$actions[]=$value==='Approve'?($stage==='publication'?'publish':$stage):strtolower($value);}
            if((in_array('hold',$actions,true)||in_array('reject',$actions,true))&&count($actions)>1){$errors[]=array('row'=>$i+1,'message'=>'Choose a single Hold/Reject, or explicit approval stages; do not combine conflicting actions.');continue;}
            $ids=null;if(trim($line[11])){if(!preg_match('/^[1-9][0-9]*(?:\s*,\s*[1-9][0-9]*){0,29}$/D',trim($line[11]))){$errors[]=array('row'=>$i+1,'message'=>'Corrected classifications require existing numeric node IDs.');continue;}$ids=array_map('intval',preg_split('/\s*,\s*/',trim($line[11])));$candidate=$row['data'];$candidate['classification']=$ids;if(trim($line[12]))$candidate['reasoning']=sanitize_textarea_field($line[12]);$valid=CAFCC_Studio::clean($candidate);if(is_wp_error($valid)){$errors[]=array('row'=>$i+1,'message'=>$valid->get_error_message());continue;}}
            if($actions||null!==$ids||trim($line[12]))$decisions[]=array('id'=>$signed['id'],'expected_revision'=>$signed['revision'],'stable_id'=>$sid,'actions'=>$actions,'classification'=>$ids,'notes'=>sanitize_textarea_field($line[12]));
        }
        if(!$errors&&$decisions){$probe=CAFCC_Academic::transaction(function()use($decisions){$r=self::execute($decisions);return is_wp_error($r)?$r:new WP_Error('cafcc_preview_rollback','Validated without committing');});if($probe->get_error_code()!=='cafcc_preview_rollback')$errors[]=array('row'=>'batch','message'=>$probe->get_error_message());}
        $token=wp_generate_uuid4();set_transient('cafcc_excel_preview_'.$token,array('owner'=>get_current_user_id(),'batch_key'=>$key,'decisions'=>$decisions,'errors'=>$errors),1800);return array('token'=>$token,'decisions'=>$decisions,'conflicts'=>$errors,'can_apply'=>!$errors&&count($decisions)>0);
    }
    private static function execute($decisions){
        try{
            foreach($decisions as $d){$r=CAFCC_Studio::get($d['id'],true);if(!$r||(int)$r['revision']!==$d['expected_revision'])throw new RuntimeException('A record changed after preview. Re-export before applying.');}
            foreach($decisions as $d){$r=CAFCC_Studio::get($d['id']);if(null!==$d['classification']||$d['notes']){$data=$r['data'];if(null!==$d['classification']){$data['classification']=$d['classification'];if($d['notes'])$data['reasoning']=$d['notes'];}$data['review_notes']=$d['notes'];$r=CAFCC_Studio::save($r['id'],array('expected_revision'=>$r['revision'],'data'=>$data));if(is_wp_error($r))throw new RuntimeException($r->get_error_message());}
                foreach($d['actions'] as $action){$r=CAFCC_Studio::decision($r['id'],array('expected_revision'=>$r['revision'],'action'=>$action,'confirmed'=>true));if(is_wp_error($r))throw new RuntimeException($r->get_error_message());}
            }
            return true;
        }catch(Throwable $e){return CAFCC_Repository::error($e->getMessage(),409);}
    }
    public static function apply($token){
        if(is_wp_error($e=CAFCC_Studio::admin()))return $e;if(!is_string($token)||!preg_match('/^[a-f0-9-]{36}$/D',$token))return CAFCC_Repository::error('Invalid decision token.');$p=get_transient('cafcc_excel_preview_'.$token);if(!$p||$p['owner']!==get_current_user_id()||$p['errors']||!$p['decisions'])return CAFCC_Repository::error('Validate a conflict-free workbook first.',409);
        // One outer transaction: nested services use savepoints below, never partial publication.
        return CAFCC_Academic::transaction(function()use($p,$token){global $wpdb;try{
            $result=self::execute($p['decisions']);if(is_wp_error($result))return $result;
            $bt=CAFCC_Bank_DB::table('batches');$wpdb->update($bt,array('status'=>'applied'),array('batch_key'=>$p['batch_key']));delete_transient('cafcc_excel_preview_'.$token);return array('applied'=>count($p['decisions']),'audit'=>'Retained per record/stage/reviewer.');
        }catch(Throwable $e){return CAFCC_Repository::error($e->getMessage(),409);}});
    }
    public static function routes(){
        $admin=function($r){return CAFCC_REST::permission($r,true);};foreach(array('export','preview','apply') as $action)register_rest_route('cafcc/v4','/admin/excel/'.$action,array('methods'=>'POST','permission_callback'=>$admin,'callback'=>function($r)use($action){$d=CAFCC_Studio::body($r,5000000);if(is_wp_error($d))return $d;return 'export'===$action?self::export($d['ids']??null):('preview'===$action?self::preview($d['base64']??null):self::apply($d['token']??null));}));
    }
}
